import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    private static long[] starts, ends, amounts, prefix;

    // Total amount in bags 1..x.
    private static long integral(long x) {
        int lo = 0, hi = starts.length; // first interval starting after x
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (starts[mid] <= x) lo = mid + 1;
            else hi = mid;
        }
        int i = lo - 1;
        if (i < 0) return 0;
        return prefix[i] + (Math.min(x, ends[i]) - starts[i] + 1) * amounts[i];
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        long[] l = new long[n], r = new long[n], v = new long[n];
        long[] order = new long[n];
        for (int i = 0; i < n; i++) {
            l[i] = nextLong();
            r[i] = nextLong();
            v[i] = nextLong();
            order[i] = (l[i] << 20) | i; // intervals are disjoint, so sorting by l sorts them
        }
        Arrays.sort(order);
        starts = new long[n];
        ends = new long[n];
        amounts = new long[n];
        prefix = new long[n + 1];
        for (int j = 0; j < n; j++) {
            int i = (int) (order[j] & ((1 << 20) - 1));
            starts[j] = l[i];
            ends[j] = r[i];
            amounts[j] = v[i];
            prefix[j + 1] = prefix[j] + (r[i] - l[i] + 1) * v[i];
        }
        // The best window starts at an interval's left end or ends at an interval's right end.
        long answer = 0;
        for (int j = 0; j < n; j++) {
            for (long start : new long[] {starts[j], Math.max(1, ends[j] - k + 1)})
                answer = Math.max(answer, integral(start + k - 1) - integral(start - 1));
        }
        System.out.println(answer % 1000000007);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

type interval struct{ l, r, v int }

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	rows := make([]interval, n)
	for i := range rows {
		rows[i] = interval{nextInt(), nextInt(), nextInt()}
	}
	// Intervals are disjoint, so sorting by l sorts them.
	slices.SortFunc(rows, func(a, b interval) int { return a.l - b.l })
	starts, prefix := make([]int, n), make([]int, n+1)
	for i, row := range rows {
		starts[i] = row.l
		prefix[i+1] = prefix[i] + (row.r-row.l+1)*row.v
	}
	// Total amount in bags 1..x.
	integral := func(x int) int {
		i := sort.Search(n, func(j int) bool { return starts[j] > x }) - 1
		if i < 0 {
			return 0
		}
		row := rows[i]
		return prefix[i] + (min(x, row.r)-row.l+1)*row.v
	}
	// The best window starts at an interval's left end or ends at an interval's right end.
	answer := 0
	for _, row := range rows {
		for _, start := range []int{row.l, max(1, row.r-k+1)} {
			answer = max(answer, integral(start+k-1)-integral(start-1))
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer%1000000007) + "\n")
}
